from sympy import Symbol, posify

def check(symbol_args):
    s = Symbol('s', **symbol_args)
    xp, _ = posify(s)
    for k, v in s._assumptions.items():
        if v is True:
            # commutativity is True by default, but let's check everything
            val = getattr(xp, 'is_' + k)
            assert val is True, f'Expected is_{k} to be True on posified symbol, got {val}'
    print(f'Symbol with {symbol_args} successfully posified, retaining all True assumptions!')

